use numpy::{IntoPyArray, PyArray1, PyReadonlyArray1};
use pyo3::prelude::*;

#[pyfunction]
fn solve<'py>(py: Python<'py>, x: PyReadonlyArray1<'py, f64>) -> Bound<'py, PyArray1<f64>> {
    let view = x.as_array();
    let out: Vec<f64> = view.iter().map(|&xi| {
        let xi_half = 0.5 * xi; // Precompute 0.5 * xi
        let term1 = xi_half - 1.2; // (0.5 * xi - 1.2)
        let term2 = term1 * xi + 0.3; // ((0.5 * xi - 1.2) * xi + 0.3)
        let term3 = term2 * xi + 2.0; // (((0.5 * xi - 1.2) * xi + 0.3) * xi + 2.0)
        let term4 = term3 * xi - 0.7; // ((((0.5 * xi - 1.2) * xi + 0.3) * xi + 2.0) * xi - 0.7)
        term4 * xi + 1.1 // (((((0.5 * xi - 1.2) * xi + 0.3) * xi + 2.0) * xi - 0.7) * xi + 1.1)
    }).collect();
    out.into_pyarray(py)
}

#[pymodule]
fn rust_solve(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(solve, m)?)?;
    Ok(())
}
